   favHeader.appendChild(h('div', {style: 'font-family:Georgia,serif;font-size:12px;color:var(--grey);'}, favIds.length + ' ' + window.locPlural(favIds.length, {fr:{one:'recette',other:'recettes'},en:{one:'recipe',other:'recipes'}})));
