   { name: (window.isEnglish && window.isEnglish() ? 'Static stretching' : 'Étirements statiques'), duration: '2 min', notes: (window.isEnglish && window.isEnglish() ? 'Worked muscle groups' : 'Groupes musculaires travaillés') }
