    alcPregDiv.appendChild(h('div', {'class': 'divider-line'}));
    alcPregDiv.appendChild(h('div', {'class': 'divider-text'}, (window.isEnglish && window.isEnglish() ? 'Alcohol consumption' : 'Consommation d\u2019alcool')));
    alcPregDiv.appendChild(h('div', {'class': 'divider-line'}));
    p.appendChild(alcPregDiv);
