// ─── MODAL ───
function renderModal(app) {
  // Attach to #app root (not the fade-in container) — position:fixed breaks when parent has CSS transform
  var root = document.getElementById('app') || app;
  var ov = h('div', {'class': 'modal-overlay' + (S.modalRecipe ? ' open' : ''), role: 'dialog', 'aria-modal': 'true', onclick: function(e) {
    if (e.target === ov) { S.modalRecipe = null; window.render(); }
  }});
  if (S.modalRecipe) {
    ov.setAttribute('tabindex', '-1');
    setTimeout(function() { if (ov) ov.focus(); }, 0);
  }
  var sheet = h('div', {'class': 'modal-sheet'});
  if (S.modalRecipe) {
    var r = S.modalRecipe;
    var hdr = h('div', {'class': 'modal-header'});
    // Bug 2: r.f or r.n may be undefined on legacy recipes
    var recipeEmoji = r.f || r.emoji || '';
    var recipeName = r.n || r.name || (window.isEnglish && window.isEnglish() ? 'Recipe' : 'Recette');
    hdr.appendChild(h('div', {'class': 'modal-title'}, recipeEmoji + (recipeEmoji ? ' ' : '') + recipeName));
    hdr.appendChild(h('button', {'class': 'modal-close', onclick: function() { S.modalRecipe = null; window.render(); }}, '\u2715'));
    sheet.appendChild(hdr);
    var body = h('div', {'class': 'modal-body'});
    var pills = h('div', {'class': 'macro-pills'});
    // Bug 3: r.k/r.p/r.g/r.l may be undefined — fallback to baseNutrition or 0
    var kcal = r.k || (r.baseNutrition && r.baseNutrition.calories) || 0;
    var prot = r.p || (r.baseNutrition && r.baseNutrition.proteinGrams) || 0;
    var carbs = r.g || (r.baseNutrition && r.baseNutrition.carbsGrams) || 0;
    var fats  = r.l || (r.baseNutrition && r.baseNutrition.fatGrams) || 0;
    pills.appendChild(h('div', {'class': 'macro-pill'}, [h('div', {'class': 'mp-val'}, String(kcal)), h('div', {'class': 'mp-label'}, 'Calories')]));
    pills.appendChild(h('div', {'class': 'macro-pill'}, [h('div', {'class': 'mp-val'}, prot + 'g'), h('div', {'class': 'mp-label'}, window.t('onb.s8.proteins'))]));
    pills.appendChild(h('div', {'class': 'macro-pill'}, [h('div', {'class': 'mp-val'}, carbs + 'g'), h('div', {'class': 'mp-label'}, window.t('onb.s8.carbs'))]));
    pills.appendChild(h('div', {'class': 'macro-pill'}, [h('div', {'class': 'mp-val'}, fats + 'g'), h('div', {'class': 'mp-label'}, window.t('onb.s8.fats'))]));
    body.appendChild(pills);
    // ═══ SCALING PORTIONS AU PROFIL UTILISATEUR ═══
    // Les recettes ont des portions fixes. On ajuste au kcal cible du slot.
    // Ex: recette 600 kcal mais slot déjeuner cible 550 kcal → facteur 0.92 → toutes qtés ×0.92
    var _scaleFactor = 1;
    try {
      var _userKcalTarget = 0;
      if (window.getCalorieTarget) _userKcalTarget = window.getCalorieTarget() || 0;
      if (_userKcalTarget > 0 && kcal > 0) {
        var _mealsPerDay = S.mealsPerDay || 4;
        // Distribution standard : petit-déj 25%, déj 35%, collation 15%, dîner 25%
        var _slotPcts = {breakfast:0.25, lunch:0.35, snack:0.15, dinner:0.25};
        var _slot = r._slot || r.slot || null;
        var _slotPct = _slotPcts[_slot] || (1 / _mealsPerDay);
        var _slotTarget = Math.round(_userKcalTarget * _slotPct);
        _scaleFactor = _slotTarget / kcal;
        // Limiter le scaling entre 0.5x et 2x (éviter portions aberrantes)
        _scaleFactor = Math.max(0.5, Math.min(2, _scaleFactor));
        // Afficher le badge scaling si facteur ≠ 1 (±5%)
        if (Math.abs(_scaleFactor - 1) > 0.05) {
          var _scaledKcal = Math.round(kcal * _scaleFactor);
          var _scaleLabel = _scaleFactor < 1 ? (window.isEnglish && window.isEnglish() ? 'Reduced portions' : 'Portions réduites') : (window.isEnglish && window.isEnglish() ? 'Increased portions' : 'Portions augmentées');
          body.appendChild(h('div', {style:'display:flex;justify-content:space-between;align-items:center;padding:8px 12px;margin-bottom:12px;background:rgba(62,92,58,0.06);border:1px solid rgba(62,92,58,0.12);border-radius:2px;font-family:"Helvetica Neue",Arial,sans-serif;font-size:11px;color:var(--green,#3E5C3A);'}, [
            h('span', {}, _scaleLabel + (window.isEnglish && window.isEnglish() ? ' for your profile' : ' pour ton profil')),
            h('span', {style:'font-weight:400'}, _scaledKcal + ' kcal (×' + _scaleFactor.toFixed(2) + ')')
          ]));
        }
      }
    } catch(_eScale) { _scaleFactor = 1; }

    body.appendChild(h('div', {'class': 'section-label'}, (window.isEnglish && window.isEnglish() ? 'Ingredients' : 'Ingr\u00e9dients')));
    var ingredList = h('ul', {'class': 'ingredient-list'});
    // Helper: display one ingredient {name, qty, unit} as a readable line
    function fmtIng(ing) {
      var name = (ing.name || '').trim();
      var rawQty = ing.qty;
      var u = (ing.unit || '').toLowerCase().trim();

      // qty=0 avec quantité intégrée dans le nom (ex: "levure chimique 1 c.à.c.")
      if (rawQty === 0 && name) {
        return name.charAt(0).toUpperCase() + name.slice(1);
      }

      // Fractions string depuis convertToDisplay ('¼', '½', '1½') — passer tel quel
      var qty = typeof rawQty === 'string' ? rawQty : (rawQty ? roundDisplayQty(rawQty, u) : '');

      // ── Unité → chaîne d'affichage ─────────────────────────────────────────
      var unitStr = '';
      if (u === 'g' || u === 'ml' || u === 'cl' || u === 'l') {
        unitStr = ' ' + u;
      } else if (u === 'kg') {
        unitStr = ' kg';
      } else if (u === 'c.à.s' || u === 'c.a.s' || u === 'cas' || u === 'càs' || u === 'cs' ||
                 u === 'c.à.soupe' || u === 'c. à soupe' || u === 'c.a.soupe') {
        unitStr = (window.isEnglish && window.isEnglish() ? ' tbsp' : ' c.à s.');
      } else if (u === 'c.à.c' || u === 'c.a.c' || u === 'cac' || u === 'càc' || u === 'cc' ||
                 u === 'c.à.café' || u === 'c.à.cafe' || u === 'c. à café' || u === 'c. à cafe') {
        unitStr = (window.isEnglish && window.isEnglish() ? ' tsp' : ' c.à c.');
      } else if (u === 'pce' || u === 'piece' || u === 'pièce' || u === 'unité' || u === 'unite') {
        unitStr = '';
      } else if (u === 'pincée' || u === 'pincee' || u === 'pincées' || u === 'pincees') {
        var qNum = parseFloat(qty);
        unitStr = ' ' + ((!isNaN(qNum) && qNum > 1) ? 'pincées' : 'pincée');
      } else if (u === 'gousse' || u === 'gousses') {
        var qGousse = parseFloat(qty);
        unitStr = ' ' + ((!isNaN(qGousse) && qGousse > 1) ? 'gousses' : 'gousse');
      } else if (u === 'avocat' || u === 'tomate' || u === 'citron' || u === 'oignon' ||
                 u === 'oignon moyen' || u === 'échalote' || u === 'echalote' ||
                 u === 'blanc' || u === 'blancs' || u === 'jaune' || u === 'jaunes') {
        unitStr = ' ' + u;
      } else if (u) {
        unitStr = ' ' + u;
      }

      // ── Normalisation noms canoniques ───────────────────────────────────────
      var _nameNorm = {
        // Œufs
        'oeuf': 'Œuf entier', 'oeuf entier': 'Œuf entier',
        'oeufs': 'Œufs', 'oeufs entiers': 'Œufs entiers',
        // Huile
        'huile': "Huile d'olive", 'huile olive': "Huile d'olive",
        // Fromage blanc
        'fromage blanc': 'Fromage blanc 0%',
        // Poulet
        'blanc de poulet': 'Blanc de poulet', 'blancs de poulet': 'Blancs de poulet',
        'filets de poulet': 'Filets de poulet',
        // Bœuf
        'boeuf haché': 'Bœuf haché maigre', 'boeuf hache': 'Bœuf haché maigre',
        'boeuf haché maigre': 'Bœuf haché maigre', 'boeuf maigre haché': 'Bœuf haché maigre',
      };
      var nameLow = name.toLowerCase();
      if (_nameNorm[nameLow]) {
        name = _nameNorm[nameLow];
      } else if (name) {
        name = name.charAt(0).toUpperCase() + name.slice(1);
      }

      return (qty + unitStr + (name ? ' ' + name : '')).trim();
    }
    // Fractions string (convertToDisplay) et qty falsy : skip scaling pour éviter NaN
    function scaleIng(ing) {
      if (_scaleFactor === 1 || !ing.qty) return ing;
      if (typeof ing.qty === 'string') return ing;
      return Object.assign({}, ing, { qty: Math.round(ing.qty * _scaleFactor * 10) / 10 });
    }
    if (r._scaledIngredients && r._scaledIngredients.length > 0) {
      r._scaledIngredients.forEach(function(ing) { ingredList.appendChild(h('li', {}, fmtIng(scaleIng(ing)))); });
    } else if (r.ingredients && Array.isArray(r.ingredients) && r.ingredients.length > 0) {
      r.ingredients.forEach(function(ing) { ingredList.appendChild(h('li', {}, fmtIng(scaleIng(ing)))); });
    } else if (r.i) {
      // Legacy string format — parse + scale les nombres
      r.i.split(',').forEach(function(raw) {
        var t = raw.trim();
        if (!t) return;
        if (_scaleFactor !== 1) {
          t = t.replace(/(\d+(?:\.\d+)?)\s*(g|ml|cl|kg)\b/gi, function(m, n, u) {
            return Math.round(parseFloat(n) * _scaleFactor) + u;
          });
        }
        ingredList.appendChild(h('li', {}, t));
      });
    } else if (r._id && window.RecipeEngine && window.RecipeEngine.findRecipe) {
      // Fallback direct RECIPES_DB lookup — always works even for old/cached weekPlans
      var fullR = window.RecipeEngine.findRecipe(r._id);
      // findRecipe() retourne un format normalisé où ingredients est une string (schéma unifié)
      if (fullR && Array.isArray(fullR.ingredients) && fullR.ingredients.length > 0) {
        fullR.ingredients.forEach(function(ing) { ingredList.appendChild(h('li', {}, fmtIng(ing))); });
      } else if (fullR && typeof fullR.ingredients === 'string' && fullR.ingredients.length > 0) {
        fullR.ingredients.split(',').forEach(function(ing) { if (ing.trim()) ingredList.appendChild(h('li', {}, ing.trim())); });
      } else {
        ingredList.appendChild(h('li', {style: 'color:var(--grey);font-style:italic'}, (window.isEnglish && window.isEnglish() ? 'Ingredients not available.' : 'Ingr\u00e9dients non disponibles.')));
      }
    } else {
      ingredList.appendChild(h('li', {style: 'color:var(--grey);font-style:italic'}, (window.isEnglish && window.isEnglish() ? 'Ingredients not available.' : 'Ingr\u00e9dients non disponibles.')));
    }
    body.appendChild(ingredList);
    body.appendChild(h('div', {'class': 'section-label'}, (window.isEnglish && window.isEnglish() ? 'Preparation' : 'Pr\u00e9paration')));
    var sl = h('ol', {'class': 'step-list'});
    var steps = Array.isArray(r.st) && r.st.length > 0 ? r.st
              : Array.isArray(r.steps) && r.steps.length > 0 ? r.steps
              : [];
    // Fallback : lookup direct dans RECIPES_DB si steps vides (cache stale ou plan ancien)
    if (steps.length === 0 && r._id && window.RecipeEngine && window.RecipeEngine.findRecipe) {
      var _fullR = window.RecipeEngine.findRecipe(r._id);
      if (_fullR && Array.isArray(_fullR.steps) && _fullR.steps.length > 0) steps = _fullR.steps;
    }
    if (steps.length === 0) {
      sl.appendChild(h('li', {style: 'color:var(--grey);font-style:italic'}, (window.isEnglish && window.isEnglish() ? 'Preparation not available for this meal.' : 'Pr\u00e9paration non disponible pour ce repas.')));
    } else {
      steps.forEach(function(s) { sl.appendChild(h('li', {}, s || '')); });
    }
    body.appendChild(sl);
    // Vérification cohérence macros : P×4 + G×4 + L×9 ≈ kcal affiché
    var chk = (prot || 0) * 4 + (carbs || 0) * 4 + (fats || 0) * 9;
    if (!isNaN(chk) && chk > 0) {
    var diffPctChk = kcal > 0 ? Math.abs((chk - kcal) / kcal * 100) : 0;
    var chkColor = diffPctChk <= 5 ? 'var(--green,#3E5C3A)' : 'var(--orange,#E86F1E)';
    body.appendChild(h('div', {'class': 'macro-check', style: 'color:' + chkColor}, (window.isEnglish && window.isEnglish() ? 'Macro check: ' + chk + ' kcal' + (diffPctChk > 5 ? ' (diff ' + Math.round(diffPctChk) + '% vs ' + kcal + ' kcal displayed)' : ' \u2713') : 'V\u00e9rification macros : ' + chk + ' kcal' + (diffPctChk > 5 ? ' (\u00e9cart ' + Math.round(diffPctChk) + '% vs ' + kcal + ' kcal affich\u00e9)' : ' \u2713'))));
    }
    var expBtn = h('button', {'class': 'btn-primary', style: 'margin-top:12px;font-size:9px', onclick: function(e) { e.stopPropagation(); window.exportRecipePDF(r); }}, (window.isEnglish && window.isEnglish() ? '\u21e9 Export this recipe to PDF' : '\u21e9 Exporter cette recette en PDF'));
    body.appendChild(expBtn);
    sheet.appendChild(body);
  }
  ov.appendChild(sheet);
  root.appendChild(ov);
  // Bug 6: reset scroll to top on each modal open
  requestAnimationFrame(function() {
    if (sheet) sheet.scrollTop = 0;
  });
}

// ─── PDF EXPORT ───
function exportDayPDF(dayIdx) {
  window.safeUserStatusCheck({ force: true }).then(function(status) {
    if (!status.isPremium) {
      if (status.source === 'fallback' && window._showPremiumCheckFailed) { window._showPremiumCheckFailed(function() { exportDayPDF(dayIdx); }); return; }
      if (window.showPaywall) window.showPaywall('pdf'); return;
    }
  if (!window.jspdf || !window.jspdf.jsPDF) {
    if (window.showToast) window.showToast((window.isEnglish && window.isEnglish()) ? 'Loading PDF…' : 'Chargement du PDF…', 'info', 2000);
    if (window._lazyLoad) { window._lazyLoad('./jspdf.umd.min.js', function() { exportDayPDF(dayIdx); }); }
    return;
  }
  if (!Array.isArray(S.weekPlan) || !S.weekPlan[dayIdx]) { if (window.showToast) window.showToast((window.isEnglish && window.isEnglish()) ? 'No plan for today \u2014 generate your weekly plan first.' : 'Aucun plan pour ce jour \u2014 g\u00e9n\u00e9rez votre plan semaine d\'abord.', 'error', 4000); return; }
  try {
  var jsPDF = window.jspdf.jsPDF;
  var doc = new jsPDF({unit: 'mm', format: 'a4'});
  var W = 210, M = 20, CW = W - 2 * M, y = 0;
  var ivory = [250, 250, 247], black = [10, 10, 9], grey = [107, 107, 101], border = [216, 216, 208];

  // Header bg
  doc.setFillColor(black[0], black[1], black[2]);
  doc.rect(0, 0, W, 38, 'F');
  doc.setTextColor(ivory[0], ivory[1], ivory[2]);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
  doc.text('SMART FIT COACH', M, 14);
  // CRITIQUE-1: garde validité dayIdx avant tout accès à DAY_NAMES/weekPlan
  if (typeof dayIdx !== 'number' || dayIdx < 0 || dayIdx > 6 || !S.weekPlan || !S.weekPlan[dayIdx]) {
    if (window.showToast) window.showToast((window.isEnglish && window.isEnglish()) ? 'No plan available for today' : 'Aucun plan disponible pour ce jour', 'error', 3000); return;
  }
  doc.setFontSize(16); doc.setFont('times', 'italic');
  doc.text((DAY_NAMES[dayIdx] || (window.isEnglish && window.isEnglish() ? 'Day' : 'Jour')) + ' \u2014 ' + (window.isEnglish && window.isEnglish() ? 'Daily Plan' : 'Plan du jour'), M, 26);
  doc.setFontSize(7); doc.setFont('helvetica', 'normal');
  var tgt = calcTarget(), mc = calcMacros() || {g:0, p:0, l:0};
  doc.text(tgt + ' kcal  |  G ' + mc.g + 'g  |  P ' + mc.p + 'g  |  L ' + mc.l + 'g', M, 33);
  y = 46;

  // Meals (guard already done above)
  var dayPlan = S.weekPlan[dayIdx];
  var slots = (window.isEnglish && window.isEnglish() ? [{key: 'breakfast', label: 'BREAKFAST'}, {key: 'lunch', label: 'LUNCH'}, {key: 'snack', label: 'SNACK'}, {key: 'dinner', label: 'DINNER'}] : [{key: 'breakfast', label: 'PETIT-D\u00c9JEUNER'}, {key: 'lunch', label: 'D\u00c9JEUNER'}, {key: 'snack', label: 'COLLATION'}, {key: 'dinner', label: 'D\u00ceNER'}]);
  var dayTotal = 0;
  slots.forEach(function(sl) {
    var r = dayPlan[sl.key]; if (!r) return; dayTotal += r.k || 0;
    if (y > 250) { doc.addPage(); y = 20; }
    doc.setFillColor(ivory[0], ivory[1], ivory[2]);
    doc.setDrawColor(border[0], border[1], border[2]);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7); doc.setTextColor(grey[0], grey[1], grey[2]);
    doc.text(sl.label, M, y); y += 5;
    doc.setFont('times', 'normal'); doc.setFontSize(13); doc.setTextColor(black[0], black[1], black[2]);
    var rNameLines = doc.splitTextToSize(r.n || (window.isEnglish && window.isEnglish() ? 'Meal' : 'Repas'), CW);
    doc.text(rNameLines, M, y); y += rNameLines.length * 5;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(grey[0], grey[1], grey[2]);
    var _macroLine = window.isEnglish && window.isEnglish() ? (r.k || 0) + ' kcal  \u00b7  C ' + (r.g || 0) + 'g  \u00b7  P ' + (r.p || 0) + 'g  \u00b7  F ' + (r.l || 0) + 'g' : (r.k || 0) + ' kcal  \u00b7  G ' + (r.g || 0) + 'g  \u00b7  P ' + (r.p || 0) + 'g  \u00b7  L ' + (r.l || 0) + 'g';
    doc.text(_macroLine, M, y); y += 6;
    doc.setFontSize(7); doc.setTextColor(grey[0], grey[1], grey[2]);
    doc.text((window.isEnglish && window.isEnglish() ? 'INGREDIENTS' : 'INGR\u00c9DIENTS'), M, y); y += 4;
    doc.setFontSize(8); doc.setTextColor(black[0], black[1], black[2]);
    var ingListPDF = r._scaledIngredients && r._scaledIngredients.length > 0
      ? r._scaledIngredients.map(function(ing) { return roundDisplayQty(ing.qty, ing.unit) + (ing.unit === 'pce' ? ' pce ' : ing.unit === 'ml' ? 'ml ' : 'g ') + ing.name; })
      : (r.i ? r.i.split(',').map(function(s) { return s.trim(); }) : []);
    ingListPDF.forEach(function(ing) {
      if (y > 275) { doc.addPage(); y = 20; }
      var ingLines = doc.splitTextToSize('\u2022  ' + (ing || ''), CW - 4);
      doc.text(ingLines, M + 2, y); y += ingLines.length * 4;
    });
    y += 2;
    doc.setFontSize(7); doc.setTextColor(grey[0], grey[1], grey[2]);
    doc.text((window.isEnglish && window.isEnglish() ? 'PREPARATION' : 'PR\u00c9PARATION'), M, y); y += 4;
    doc.setFontSize(8); doc.setTextColor(black[0], black[1], black[2]);
    (r.st || []).forEach(function(step, si) {
      if (y > 275) { doc.addPage(); y = 20; }
      var lines = doc.splitTextToSize((si + 1) + '. ' + step, CW - 6);
      lines.forEach(function(line) { doc.text(line, M + 2, y); y += 4; });
    });
    y += 4;
    doc.setDrawColor(border[0], border[1], border[2]);
    doc.line(M, y, W - M, y); y += 6;
  });

  // Total
  if (y > 265) { doc.addPage(); y = 20; }
  doc.setFillColor(244, 244, 240);
  doc.rect(M, y - 2, CW, 10, 'F');
  doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(grey[0], grey[1], grey[2]);
  doc.text((window.isEnglish && window.isEnglish() ? 'DAILY TOTAL' : 'TOTAL DU JOUR'), M + 4, y + 4);
  doc.setFont('times', 'normal'); doc.setFontSize(12); doc.setTextColor(black[0], black[1], black[2]);
  doc.text(dayTotal + ' kcal', W - M - 4, y + 4, {align: 'right'}); y += 14;

  // Medical warnings
  if (Array.isArray(S.medical) && S.medical.length > 0) {
    doc.setFontSize(7); doc.setTextColor(106, 74, 26);
    doc.text((window.isEnglish && window.isEnglish() ? 'MEDICAL RECOMMENDATIONS' : 'RECOMMANDATIONS M\u00c9DICALES'), M, y); y += 4;
    doc.setFontSize(7); doc.setTextColor(grey[0], grey[1], grey[2]);
    S.medical.forEach(function(id) {
      var adv = MEDICAL_ADVICE[id];
      if (adv) { if (y > 275) { doc.addPage(); y = 20; } doc.text('\u2022 ' + adv.warn, M + 2, y); y += 4; }
    }); y += 4;
  }

  // Footer
  var pages = doc.internal.getNumberOfPages();
  for (var i = 1; i <= pages; i++) {
    doc.setPage(i); doc.setFontSize(6); doc.setTextColor(grey[0], grey[1], grey[2]);
    doc.text((window.isEnglish && window.isEnglish() ? 'Smart Fit Coach \u2014 generated on ' : 'Smart Fit Coach \u2014 g\u00e9n\u00e9r\u00e9 le ') + window.formatDate(new Date()), M, 290);
    doc.text('Page ' + i + '/' + pages, W - M, 290, {align: 'right'});
  }
  var safeDayName = (DAY_NAMES[dayIdx] || 'jour').toLowerCase()
    .replace(/[àáâãäå]/g, 'a').replace(/[èéêë]/g, 'e')
    .replace(/[îï]/g, 'i').replace(/[ôõö]/g, 'o')
    .replace(/[ùûü]/g, 'u').replace(/ç/g, 'c').replace(/ñ/g, 'n')
    .replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
  doc.save('plan-' + (safeDayName || 'jour') + '.pdf');
  } catch(e) { console.error('[exportDayPDF] Erreur:', e); if (window.showToast) window.showToast((window.isEnglish && window.isEnglish()) ? 'Error generating PDF. Check your data.' : 'Erreur lors de la g\u00e9n\u00e9ration du PDF. V\u00e9rifiez vos donn\u00e9es.', 'error', 4000); }
  }); // end safeUserStatusCheck.then
}
window.exportDayPDF = exportDayPDF;

function exportRecipePDF(r) {
  window.safeUserStatusCheck({ force: true }).then(function(status) {
    if (!status.isPremium) {
      if (status.source === 'fallback' && window._showPremiumCheckFailed) { window._showPremiumCheckFailed(function() { exportRecipePDF(r); }); return; }
      if (window.showPaywall) window.showPaywall('pdf'); return;
    }
  if (!window.jspdf || !window.jspdf.jsPDF) {
    if (window.showToast) window.showToast((window.isEnglish && window.isEnglish()) ? 'Loading PDF…' : 'Chargement du PDF…', 'info', 2000);
    if (window._lazyLoad) { window._lazyLoad('./jspdf.umd.min.js', function() { exportRecipePDF(r); }); }
    return;
  }
  if (!r || !r.n) { if (window.showToast) window.showToast((window.isEnglish && window.isEnglish()) ? 'Recipe not available for export' : 'Recette non disponible pour l\u2019export', 'error', 3000); return; }
  try {
  var jsPDF = window.jspdf.jsPDF;
  var doc = new jsPDF({unit: 'mm', format: 'a4'});
  var W = 210, M = 20, CW = W - 2 * M, y = 0;
  var ivory = [250, 250, 247], black = [10, 10, 9], grey = [107, 107, 101], border = [216, 216, 208];

  // Header
  doc.setFillColor(black[0], black[1], black[2]);
  doc.rect(0, 0, W, 34, 'F');
  doc.setTextColor(ivory[0], ivory[1], ivory[2]);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
  doc.text('SMART FIT COACH', M, 12);
  doc.setFont('times', 'italic'); doc.setFontSize(18);
  var recTitleLines = doc.splitTextToSize(r.n || 'Recette', W - 2 * M);
  doc.text(recTitleLines, M, 25);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
  doc.text((r.k || 0) + ' kcal  |  G ' + (r.g || 0) + 'g  |  P ' + (r.p || 0) + 'g  |  L ' + (r.l || 0) + 'g', M, 31);
  y = 44;

  // Macro boxes
  var macros = (window.isEnglish && window.isEnglish() ? [{l: 'CALORIES', v: String(r.k || 0)}, {l: 'PROTEIN', v: (r.p || 0) + 'g'}, {l: 'CARBS', v: (r.g || 0) + 'g'}, {l: 'FAT', v: (r.l || 0) + 'g'}] : [{l: 'CALORIES', v: String(r.k || 0)}, {l: 'PROT\u00c9INES', v: (r.p || 0) + 'g'}, {l: 'GLUCIDES', v: (r.g || 0) + 'g'}, {l: 'LIPIDES', v: (r.l || 0) + 'g'}]);
  var bw = CW / 4 - 2;
  macros.forEach(function(mc2, i) {
    var x = M + i * (bw + 2.6);
    doc.setFillColor(244, 244, 240); doc.setDrawColor(border[0], border[1], border[2]);
    doc.rect(x, y, bw, 14, 'FD');
    doc.setFont('times', 'normal'); doc.setFontSize(14); doc.setTextColor(black[0], black[1], black[2]);
    doc.text(mc2.v, x + bw / 2, y + 7, {align: 'center'});
    doc.setFont('helvetica', 'normal'); doc.setFontSize(6); doc.setTextColor(grey[0], grey[1], grey[2]);
    doc.text(mc2.l, x + bw / 2, y + 12, {align: 'center'});
  }); y += 22;

  // Ingredients
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7); doc.setTextColor(grey[0], grey[1], grey[2]);
  doc.text((window.isEnglish && window.isEnglish() ? 'INGREDIENTS' : 'INGR\u00c9DIENTS'), M, y);
  doc.setDrawColor(border[0], border[1], border[2]); doc.line(M, y + 1.5, W - M, y + 1.5); y += 6;
  doc.setFontSize(9); doc.setTextColor(black[0], black[1], black[2]);
  var recipeIngPDF = r._scaledIngredients && r._scaledIngredients.length > 0
    ? r._scaledIngredients.map(function(ing) { return roundDisplayQty(ing.qty, ing.unit) + (ing.unit === 'pce' ? ' pce ' : ing.unit === 'ml' ? 'ml ' : 'g ') + ing.name; })
    : (r.i ? r.i.split(',').map(function(s) { return s.trim(); }) : []);
  recipeIngPDF.forEach(function(ing) {
    if (y > 275) { doc.addPage(); y = 20; }
    var ingLines = doc.splitTextToSize('\u2022  ' + (ing || ''), CW - 4);
    doc.text(ingLines, M + 2, y); y += ingLines.length * 5;
  }); y += 4;

  // Steps
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7); doc.setTextColor(grey[0], grey[1], grey[2]);
  doc.text((window.isEnglish && window.isEnglish() ? 'PREPARATION' : 'PR\u00c9PARATION'), M, y);
  doc.setDrawColor(border[0], border[1], border[2]); doc.line(M, y + 1.5, W - M, y + 1.5); y += 6;
  doc.setFontSize(9); doc.setTextColor(black[0], black[1], black[2]);
  (r.st || []).forEach(function(step, si) {
    if (y > 275) { doc.addPage(); y = 20; }
    var lines = doc.splitTextToSize((si + 1) + '. ' + step, CW - 8);
    lines.forEach(function(line) { doc.text(line, M + 2, y); y += 5; });
    y += 2;
  });

  // Footer
  doc.setFontSize(6); doc.setTextColor(grey[0], grey[1], grey[2]);
  doc.text('Smart Fit Coach', M, 290);
  var safeName = (r.n || (window.isEnglish && window.isEnglish() ? 'recipe' : 'recette')).toLowerCase()
    .replace(/[àáâãäå]/g, 'a').replace(/[èéêë]/g, 'e')
    .replace(/[îï]/g, 'i').replace(/[ôõö]/g, 'o')
    .replace(/[ùûü]/g, 'u').replace(/ç/g, 'c').replace(/ñ/g, 'n')
    .replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
  doc.save((safeName || (window.isEnglish && window.isEnglish() ? 'recipe' : 'recette')) + '.pdf');
  } catch(e) { console.error('[exportRecipePDF] Erreur:', e); if (window.showToast) window.showToast((window.isEnglish && window.isEnglish()) ? 'Error generating recipe PDF' : 'Erreur lors de la g\u00e9n\u00e9ration du PDF recette', 'error', 3500); }
  }); // end safeUserStatusCheck.then
}
window.exportRecipePDF = exportRecipePDF;

// ─── SHOPPING LIST HELPERS ───
function cleanShopChecked(list) {
  if (!window.S || !window.S.shopChecked) return;
  var validNames = {};
  list.forEach(function(cat) {
    cat.items.forEach(function(item) { validNames[item.name] = true; });
  });
  Object.keys(window.S.shopChecked).forEach(function(k) {
    if (!validNames[k]) delete window.S.shopChecked[k];
  });
}

